import { ethers } from 'ethers';
import { decodeError } from '@/lib/contracts/error-decoder';

// The *.json files next to this are generated by the voucher repo's
// scripts/exportWebappArtifacts.ts (ABI + creation bytecode) — rerun it after any
// voucher contract change instead of editing them by hand. Kept in this subfolder so
// scripts/snapshot-abi-version.js (top-level lib/contracts/*.json only) doesn't pick them up.
import VoucherNFT from './VoucherNFT.json';
import VoucherDAO from './VoucherDAO.json';
import RevocationVault from './RevocationVault.json';
import AllowlistTransferGate from './AllowlistTransferGate.json';
import SourceRegistry from './SourceRegistry.json';
import VoucherNFTViews from './VoucherNFTViews.json';
import RewardSink from './RewardSink.json';
import VoucherIncentive from './VoucherIncentive.json';
import VoucherTransfer from './VoucherTransfer.json';
import ERC1967Proxy from './ERC1967Proxy.json';
import manifest from './manifest.json';

/** When / from which voucher-repo commit the JSON files above were exported. */
export const ARTIFACT_MANIFEST = manifest as { exportedAt: string; gitCommit: string; gitDirty: boolean };

type Artifact = { contractName: string; abi: any[]; bytecode: string };

export const ARTIFACTS = {
  VoucherNFT,
  VoucherDAO,
  RevocationVault,
  AllowlistTransferGate,
  SourceRegistry,
  VoucherNFTViews,
  RewardSink,
  VoucherIncentive,
  VoucherTransfer,
  ERC1967Proxy,
} as Record<string, Artifact>;

export type ContractKey =
  | 'VoucherNFT'
  | 'VoucherDAO'
  | 'RevocationVault'
  | 'AllowlistTransferGate'
  | 'SourceRegistry'
  | 'VoucherNFTViews'
  | 'RewardSink'
  | 'VoucherIncentive'
  | 'VoucherTransfer';

export const ZERO = ethers.constants.AddressZero;
export const MAX_UINT = ethers.constants.MaxUint256.toString(); // VoucherRateLimit.UNLIMITED
export const DEFAULT_ADMIN_ROLE = ethers.constants.HashZero;
export const role = (name: string) => ethers.utils.id(name);

// Ordinals of VoucherNFT's enums.
export const VoucherMode = { Points: 0, Reward: 1 } as const;
export const TokenStandard = { Native: 0, ERC20: 1, ERC721: 2, ERC1155: 3 } as const;
export const RewardTiming = { Immediate: 0, Deferred: 1 } as const;
export const PointsDirection = { Credit: 0, Debit: 1 } as const;
export const PayoutMode = { Direct: 0, Routed: 1, External: 2 } as const;
export const enumName = (e: Record<string, number>, v: number) => Object.keys(e).find((k) => e[k] === Number(v)) || String(v);

export const isAddr = (a: string) => !!a && ethers.utils.isAddress(a.trim());
export const sameAddr = (a?: string, b?: string) => !!a && !!b && a.toLowerCase() === b.toLowerCase();
export const shortAddr = (a: string) => (a ? `${a.slice(0, 6)}…${a.slice(-4)}` : '—');

// ── Address book (per chain, localStorage) ──

export interface Book {
  contracts: Partial<Record<ContractKey, string>>;
  implementations: Partial<Record<ContractKey, string>>;
  // implementation deployed but proxy tx not confirmed yet — retry reuses it
  pendingImpl: Partial<Record<ContractKey, string>>;
  tokens: Record<string, string>;
  // extra RewardSink pools beyond the main one (contracts.RewardSink) — any number, each a proxy
  extraSinks: { name: string; address: string; implementation: string }[];
  deployedAt: string | null;
  // lastChangeAt > lastExportAt means addresses exist only in this browser — nag to export
  lastChangeAt?: string;
  lastExportAt?: string;
}

export const emptyBook = (): Book => ({ contracts: {}, implementations: {}, pendingImpl: {}, tokens: {}, extraSinks: [], deployedAt: null });
const bookKey = (chainId: number) => `dg_voucherV2Book:${chainId}`;

// SourceRegistry was called FundingSourceRegistry before it also held payout destinations —
// books/exports saved under the old key still load.
const RENAMED: Record<string, string> = { FundingSourceRegistry: 'SourceRegistry' };
const migrateKeys = <T,>(m: Record<string, T> = {}) =>
  Object.fromEntries(Object.entries(m).map(([k, v]) => [RENAMED[k] || k, v])) as Record<string, T>;

export function loadBook(chainId: number): Book {
  try {
    const raw = localStorage.getItem(bookKey(chainId));
    if (raw) {
      const b = { ...emptyBook(), ...JSON.parse(raw) } as Book;
      return { ...b, contracts: migrateKeys(b.contracts), implementations: migrateKeys(b.implementations), pendingImpl: migrateKeys(b.pendingImpl) };
    }
  } catch {
    // unreadable / blocked storage — start empty
  }
  return emptyBook();
}

export function saveBook(chainId: number, book: Book) {
  try {
    localStorage.setItem(bookKey(chainId), JSON.stringify(book));
  } catch {
    // storage unavailable — the book still works for this session
  }
}

/** Accepts this tab's own export or the voucher repo's deployments/<network>.json. */
export function parseBookImport(text: string, chainId: number): Book {
  const parsed = JSON.parse(text);
  if (parsed.chainId && Number(parsed.chainId) !== chainId) {
    throw new Error(`This file is for chainId ${parsed.chainId}, but the wallet is on ${chainId}`);
  }
  const source = parsed.contracts || parsed;
  const book = emptyBook();
  for (const [rawKey, v] of Object.entries(source)) {
    const k = RENAMED[rawKey] || rawKey;
    if (typeof v !== 'string' || !ethers.utils.isAddress(v)) continue;
    const addr = ethers.utils.getAddress(v);
    if (k in ARTIFACTS && k !== 'ERC1967Proxy') book.contracts[k as ContractKey] = addr;
    else book.tokens[k] = addr; // e.g. "MockERC20 (18dp)"
  }
  Object.assign(book.tokens, parsed.tokens || {});
  if (Array.isArray(parsed.extraSinks)) {
    book.extraSinks = parsed.extraSinks.filter((x: any) => x && ethers.utils.isAddress(x.address))
      .map((x: any) => ({ name: String(x.name || ''), address: ethers.utils.getAddress(x.address), implementation: x.implementation || '' }));
  }
  Object.assign(book.implementations, migrateKeys(parsed.implementations));
  book.deployedAt = parsed.deployedAt || null;
  return book;
}

// ── Errors ──

// Every custom error across the voucher contracts (shared VoucherErrors catalog + OZ errors),
// deduped by name so ethers doesn't warn about duplicate fragments.
const errorIface = (() => {
  const seen = new Set<string>();
  const frags: any[] = [];
  for (const a of Object.values(ARTIFACTS)) {
    for (const f of a.abi) {
      if (f.type !== 'error' || seen.has(f.name)) continue;
      seen.add(f.name);
      frags.push(f);
    }
  }
  return new ethers.utils.Interface(frags);
})();

export function decodeVoucherError(e: any): string {
  const candidates = [e?.error?.data?.data, e?.error?.data, e?.data?.data, e?.data, e?.error?.error?.data];
  for (const c of candidates) {
    if (typeof c !== 'string' || !c.startsWith('0x') || c.length < 10) continue;
    try {
      const parsed = errorIface.parseError(c);
      if (parsed.name === 'AccessControlUnauthorizedAccount') {
        return `Access denied: ${shortAddr(parsed.args[0])} is missing role ${roleName(parsed.args[1])}`;
      }
      if (parsed.name === 'AutoExecuteOutOfGas') {
        return 'Reverted: AutoExecuteOutOfGas — not enough gas to run the proposal once quorum was reached. Send it again with a higher gas limit.';
      }
      if (parsed.name === 'AddressRestricted') {
        return "Reverted: AddressRestricted — the pool's access control blocks this payout (claimer blacklisted, or frozen with no safe wallet). The voucher stays claimable.";
      }
      return `Reverted: ${parsed.name}`;
    } catch {
      // not one of ours
    }
  }
  const reason = e?.reason || e?.error?.reason;
  if (reason) return String(reason).replace(/^execution reverted: /, '');
  return decodeError(e);
}

const KNOWN_ROLES = [
  'TYPE_ADMIN_ROLE', 'REVOKE_ROLE', 'REGISTRY_ADMIN_ROLE', 'ALLOWLIST_ADMIN_ROLE',
  'SETTLER_ROLE', 'SETTLER_PROPOSER_ROLE', 'SETTLER_APPROVER_ROLE',
];
function roleName(hash: string) {
  if (hash === DEFAULT_ADMIN_ROLE) return 'DEFAULT_ADMIN_ROLE';
  return KNOWN_ROLES.find((r) => role(r) === hash) || `${hash.slice(0, 10)}… (per-type role)`;
}

// ── Amounts ──

export const toUnits = (amount: string, decimals: number) => ethers.utils.parseUnits((amount || '0').trim(), decimals).toString();
export const fromUnits = (raw: ethers.BigNumberish, decimals: number) => {
  const s = ethers.utils.formatUnits(raw, decimals);
  return s.endsWith('.0') ? s.slice(0, -2) : s;
};

// ── Voucher types ──

export interface VoucherType {
  id: number;
  name: string;
  redemptionDays: number;
  transferable: boolean;
  mintApprovalsRequired: number;
  mode: number;
  tokenStandard: number;
  mintingPaused: boolean;
  redemptionPaused: boolean;
  payoutRecipient: string;
  fundingSource: string;
  rewardTiming: number;
  pointsDirection: number;
  transferGate: string;
  revokeDestination: string;
  payoutMode: number;
  routeTarget: string;
  approvedTokens: string[];
}

export async function loadVoucherTypes(nft: ethers.Contract): Promise<VoucherType[]> {
  const count = (await nft.nextTypeId()).toNumber();
  return Promise.all(
    Array.from({ length: count }, async (_, id) => {
      const [t, approvedTokens] = await Promise.all([nft.voucherTypes(id), nft.getApprovedTokens(id)]);
      return {
        id,
        name: t.name,
        redemptionDays: Number(t.redemptionDays),
        transferable: t.transferable,
        mintApprovalsRequired: Number(t.mintApprovalsRequired),
        mode: Number(t.mode),
        tokenStandard: Number(t.tokenStandard),
        mintingPaused: t.mintingPaused,
        redemptionPaused: t.redemptionPaused,
        payoutRecipient: t.payoutRecipient,
        fundingSource: t.fundingSource,
        rewardTiming: Number(t.rewardTiming),
        pointsDirection: Number(t.pointsDirection),
        transferGate: t.transferGate,
        revokeDestination: t.revokeDestination,
        payoutMode: Number(t.payoutMode),
        routeTarget: t.routeTarget,
        approvedTokens: [...approvedTokens],
      };
    })
  );
}

export function kindOf(t: VoucherType) {
  return t.mode === VoucherMode.Points
    ? `Points ${enumName(PointsDirection, t.pointsDirection)}`
    : `Reward ${enumName(TokenStandard, t.tokenStandard)}${t.rewardTiming === RewardTiming.Deferred ? ' (deferred)' : ''}`;
}
// "#2 Weekly bonus · Reward Native" — the kind is left out when the name already says it
export const typeLabel = (t: VoucherType) => {
  const kind = kindOf(t);
  return t.name.toLowerCase().includes(kind.toLowerCase()) ? `#${t.id} ${t.name}` : `#${t.id} ${t.name} · ${kind}`;
};

/** First arg of the first `eventName` log emitted by `contract` in this receipt. */
export function eventArg(receipt: ethers.ContractReceipt, contract: ethers.Contract, eventName: string, arg: string): any {
  for (const log of receipt.logs) {
    if (!sameAddr(log.address, contract.address)) continue;
    try {
      const parsed = contract.interface.parseLog(log);
      if (parsed.name === eventName) return parsed.args[arg];
    } catch {
      // other event
    }
  }
  throw new Error(`${eventName} not found in receipt`);
}

/**
 * Public BSC RPCs (and the multi-RPC fallback provider) can answer from a replica that
 * hasn't seen the write yet — poll until the read settles to what's expected.
 */
export async function settledRead<T>(read: () => Promise<T>, ok: (v: T) => boolean, attempts = 5, delayMs = 2500): Promise<T | undefined> {
  let last: T | undefined;
  for (let i = 0; i < attempts; i++) {
    try {
      last = await read();
      if (ok(last)) return last;
    } catch {
      last = undefined;
    }
    if (i < attempts - 1) await new Promise((r) => setTimeout(r, delayMs));
  }
  return last;
}
